#pragma once

// The interface thread of Apple Music's main window, for the kernel's facade (ui_thread.hpp). Compiled only with
// AMPIFY_WITH_XAML (C++/WinRT projection of the Windows App SDK, generated by the MSVC job). The bench case
// 63-ui-surfaces checks the log lines written here. Apple's windows themselves: xaml_chrome.hpp.

#if defined(AMPIFY_WITH_XAML)

#include <cstdint>
#include <string>

#include <winrt/Microsoft.UI.Dispatching.h>

#include "xaml_chrome.hpp"

#include "win_common.hpp"
#ifdef GetCurrentTime
#undef GetCurrentTime  // windows.h macro that breaks Storyboard::GetCurrentTime in the projection
#endif

namespace ampify::win {

// Installs the DispatcherQueue backend of the interface-thread facade (ui_thread.hpp): AttachUiThread takes the main
// window from AppWindowOf(WindowRole::Main), PostToUiThread runs the work through its DispatcherQueue at Low priority,
// inside try/catch. Writes the log lines "Interface: main window obtained ..." and "Interface: first
// work run by the main window's DispatcherQueue ...". Call once, before AttachUiThread.
void InstallXamlUiThread(Journal& journal);

// Milliseconds since boot, for the refresh tickets.
std::uint64_t NowMs() noexcept;

// A WinRT string as UTF-8, for the log and the core.
inline std::string Utf8(const winrt::hstring& text) {
    return winrt::to_string(text);
}

}  // namespace ampify::win

#endif  // AMPIFY_WITH_XAML
